#!/usr/bin/env python3
"""Generate a deterministic Flutter widget test that traces the REAL render of the on-line page.

Invariant ③ requires comparing the real component render (bbox/token/text per node) against the
design-derived render_plan — NOT a golden image, NOT the model's eyeballing. To get the *real*
geometry we pump the actual page (fed the SAME fixture) in a widget test sized to the design
artboard (u=1, so logical px == design px) and, for every node carrying `ValueKey('iff:<id>')`,
record `tester.getRect` plus the rendered Text/Decoration style. The emitted JSON
(`actual_layout_trace.json`) is then diffed by `check_render_fidelity.py`.

The node id list + artboard dimensions come from `generate_canvas`'s `*.expected.json` sidecar, so
the trace covers exactly the keyed (placed) nodes. The test is fully generated (no hand edits):
the page-under-test is parameterised so the same harness works for the home canvas and for any
data-driven component page that mounts the keyed primitives.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

TEMPLATE = r"""// GENERATED by iFF gen_layout_trace_test.py — DO NOT EDIT BY HAND.
// 真实渲染 layout trace:按设计画板尺寸 pump 真实页面(u=1,逻辑像素==设计像素),
// 对每个挂了 ValueKey('iff:<id>') 的节点记录 getRect + 文本/装饰样式,写出
// actual_layout_trace.json canonical shape: {"pageType": "...", "nodes": {"<node id>": {...}}}.
// 供 make_repair_plan.py、check_render_fidelity.py 和 completion gate 逐组件校验。
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
__PAGE_IMPORT__
__EXTRA_IMPORTS__
void main() {
  testWidgets('iff layout trace (real render vs render_plan)', (WidgetTester tester) async {
    const double dw = __DW__;
    const double dh = __DH__;
    tester.view.physicalSize = const Size(dw, dh);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(() {
      tester.view.resetPhysicalSize();
      tester.view.resetDevicePixelRatio();
    });

    await tester.pumpWidget(MaterialApp(
      debugShowCheckedModeBanner: false,
      home: __PAGE_EXPR__,
    ));
    // 必须 trace 真实上线页(不变量②⑥:验收对象==上线对象),页面常异步加载数据后才
    // 挂出可见层 —— 喂同源设计 fixture 时 Future 在下一个 microtask 完成,连泵几帧让它
    // 渲染到位(同时把无真机图片字节的 asset 解码异常排掉,固定尺寸几何不受影响)。
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 350));
    await tester.pump(const Duration(seconds: 1));
    while (tester.takeException() != null) {}

    const List<String> ids = <String>[__IDS__];
    final Map<String, dynamic> nodes = <String, dynamic>{};

    Offset pageOrigin = Offset.zero;
    final Finder pageFinder = find.byType(__PAGE_TYPE__);
    if (pageFinder.evaluate().isNotEmpty) {
      pageOrigin = tester.getRect(pageFinder.first).topLeft;
    }

    for (final String id in ids) {
      final Finder f = find.byKey(ValueKey<String>('iff:$id'));
      if (f.evaluate().isEmpty) {
        nodes[id] = <String, dynamic>{'present': false};
        continue;
      }
      final Rect r = tester.getRect(f.first);
      final Map<String, dynamic> rec = <String, dynamic>{
        'present': true,
        'bbox': <double>[
          r.left - pageOrigin.dx,
          r.top - pageOrigin.dy,
          r.width,
          r.height,
        ],
      };
      final Finder tf = find.descendant(of: f.first, matching: find.byType(Text));
      if (tf.evaluate().isNotEmpty) {
        final Text t = tester.widget<Text>(tf.first);
        rec['fontSize'] = t.style?.fontSize;
        rec['colorArgb'] = t.style?.color?.toARGB32();
        rec['text'] = t.data ?? t.textSpan?.toPlainText();
      }
      // 表单输入值由真实 TextField 承载(IMPL-FORM-2):它渲染 EditableText 而非 Text,
      // 这里读其当前文本/样式,使输入值节点同样可被逐组件保真校验。
      if (rec['text'] == null) {
        final Finder ef = find.descendant(of: f.first, matching: find.byType(EditableText));
        if (ef.evaluate().isNotEmpty) {
          final EditableText e = tester.widget<EditableText>(ef.first);
          rec['text'] = e.controller.text;
          rec['fontSize'] = e.style.fontSize;
          rec['colorArgb'] = e.style.color?.toARGB32();
        }
      }
      final Finder df = find.descendant(of: f.first, matching: find.byType(DecoratedBox));
      if (df.evaluate().isNotEmpty) {
        final DecoratedBox d = tester.widget<DecoratedBox>(df.first);
        final Decoration dec = d.decoration;
        if (dec is BoxDecoration) {
          if (dec.color != null) rec['colorArgb'] = dec.color!.toARGB32();
          final BorderRadiusGeometry? br = dec.borderRadius;
          if (br is BorderRadius) rec['radius'] = br.topLeft.x;
        } else if (dec is ShapeDecoration) {
          if (dec.color != null) rec['colorArgb'] = dec.color!.toARGB32();
        }
      }
      nodes[id] = rec;
    }

    final File out = File(r'__TRACE_OUT__');
    out.parent.createSync(recursive: true);
    out.writeAsStringSync(const JsonEncoder.withIndent('  ').convert(<String, dynamic>{
      'pageType': '__PAGE_TYPE_STR__',
      'expectedNodeIds': ids,
      'nodes': nodes,
    }));
    // 至少要找到一个节点,否则页面根本没渲染(0x0 collapse / 路由错挂)——直接失败。
    final int present =
        nodes.values.where((dynamic v) => (v as Map)['present'] == true).length;
    expect(present, greaterThan(0),
        reason: 'no keyed iff node rendered — page collapsed or wrong page mounted');
  });

  testWidgets('iff responsive layout contract (375 logical constraints)',
      (WidgetTester tester) async {
    const Map<String, Map<String, List<double>>> expectedRectsByViewport =
        <String, Map<String, List<double>>>{__RESPONSIVE_RECTS__};
    const List<List<double>> viewports = <List<double>>[__VIEWPORTS__];
    final List<Map<String, dynamic>> cases = <Map<String, dynamic>>[];
    final List<String> failures = <String>[];
    tester.view.devicePixelRatio = 1.0;
    addTearDown(() {
      tester.view.resetPhysicalSize();
      tester.view.resetDevicePixelRatio();
    });

    for (final List<double> viewport in viewports) {
      final double width = viewport[0];
      final double height = viewport[1];
      final Map<String, List<double>> expectedRects =
          expectedRectsByViewport['${width}x$height']!;
      tester.view.physicalSize = Size(width, height);
      await tester.pumpWidget(MaterialApp(
        debugShowCheckedModeBanner: false,
        home: __PAGE_EXPR__,
      ));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 350));
      await tester.pump(const Duration(seconds: 1));

      final List<String> layoutErrors = <String>[];
      Object? exception;
      while ((exception = tester.takeException()) != null) {
        final String message = '$exception';
        final String lower = message.toLowerCase();
        if (lower.contains('overflowed') ||
            lower.contains('boxconstraints') ||
            lower.contains('infinite size')) {
          layoutErrors.add(message);
        }
      }

      final Finder pageFinder = find.byType(__PAGE_TYPE__);
      Offset pageOrigin = Offset.zero;
      if (pageFinder.evaluate().isNotEmpty) {
        pageOrigin = tester.getRect(pageFinder.first).topLeft;
      } else {
        layoutErrors.add('online page type __PAGE_TYPE_STR__ was not mounted');
      }

      final List<String> missing = <String>[];
      double maxDelta = 0.0;
      String? worstNode;
      String? worstAxis;
      double? worstExpected;
      double? worstObserved;
      for (final MapEntry<String, List<double>> entry in expectedRects.entries) {
        final Finder finder = find.byKey(ValueKey<String>('iff:${entry.key}'));
        if (finder.evaluate().isEmpty) {
          missing.add(entry.key);
          continue;
        }
        final Rect rect = tester.getRect(finder.first);
        final List<double> observed = <double>[
          rect.left - pageOrigin.dx,
          rect.top - pageOrigin.dy,
          rect.width,
          rect.height,
        ];
        for (int index = 0; index < 4; index += 1) {
          final double delta = (observed[index] - entry.value[index]).abs();
          if (delta > maxDelta) {
            maxDelta = delta;
            worstNode = entry.key;
            worstAxis = const <String>['x', 'y', 'w', 'h'][index];
            worstExpected = entry.value[index];
            worstObserved = observed[index];
          }
        }
      }
      final bool passed = missing.isEmpty && layoutErrors.isEmpty && maxDelta <= 2.0;
      final Map<String, dynamic> result = <String, dynamic>{
        'width': width,
        'height': height,
        'runtimeScale': 1,
        'missing': missing,
        'layoutErrors': layoutErrors,
        'maxLogicalBboxDelta': maxDelta,
        'worstNode': worstNode,
        'worstAxis': worstAxis,
        'worstExpected': worstExpected,
        'worstObserved': worstObserved,
        'pass': passed,
      };
      cases.add(result);
      if (!passed) failures.add('$width x $height: $result');
      await tester.pumpWidget(const SizedBox.shrink());
    }

    final File out = File(r'__RESPONSIVE_OUT__');
    out.parent.createSync(recursive: true);
    out.writeAsStringSync(const JsonEncoder.withIndent('  ').convert(<String, dynamic>{
      'schemaVersion': 2,
      'policy': 'logical_375_constraints',
      'pageType': '__PAGE_TYPE_STR__',
      'cases': cases,
      'pass': failures.isEmpty,
    }));
    expect(failures, isEmpty,
        reason: 'responsive layout contract failed: ${failures.join('; ')}');
  });
}
"""


def _load_expected_contract(requested_path: Path, trace_out: Path) -> dict:
    """Adopt the board's merged expectation when given a canvas sidecar."""
    requested = json.loads(requested_path.read_text(encoding="utf-8"))
    merged_path = trace_out.parent / "merged_expected.json"
    if merged_path.resolve() == requested_path.resolve() or not merged_path.is_file():
        return requested

    merged = json.loads(merged_path.read_text(encoding="utf-8"))
    nodes = dict(merged.get("nodes") or {})
    nodes.update(requested.get("nodes") or {})
    adopted = dict(merged)
    adopted["nodes"] = nodes
    for key in ("artboardWidth", "artboardHeight"):
        if requested.get(key) is not None:
            adopted[key] = requested[key]
    print(f"adopted canonical merged expectation {merged_path} "
          f"({len(nodes)} node(s); current canvas nodes override stale base entries)")
    return adopted


def _parse_viewports(raw: str) -> list[tuple[float, float]]:
    parsed: list[tuple[float, float]] = []
    for token in raw.split(","):
        parts = token.strip().lower().split("x")
        if len(parts) != 2:
            raise SystemExit(f"ERROR: invalid viewport {token!r}; expected WIDTHxHEIGHT")
        width, height = float(parts[0]), float(parts[1])
        if width <= 0 or height <= 0:
            raise SystemExit(f"ERROR: viewport dimensions must be positive: {token!r}")
        parsed.append((width, height))
    if len(parsed) < 3:
        raise SystemExit("ERROR: responsive verification requires at least 3 target viewports")
    return parsed


def _load_viewports(raw: str, source: Path | None) -> list[tuple[float, float]]:
    if source is None:
        return _parse_viewports(raw)
    payload = json.loads(source.read_text(encoding="utf-8"))
    records = payload.get("viewports") if isinstance(payload, dict) else payload
    if not isinstance(records, list):
        raise SystemExit("ERROR: --viewports-file must be a list or {\"viewports\": [...]}")
    parsed: list[tuple[float, float]] = []
    for record in records:
        if not isinstance(record, dict) or "width" not in record or "height" not in record:
            raise SystemExit("ERROR: every target viewport requires width and height")
        width, height = float(record["width"]), float(record["height"])
        if width <= 0 or height <= 0:
            raise SystemExit("ERROR: target viewport dimensions must be positive")
        parsed.append((width, height))
    if len(parsed) < 3:
        raise SystemExit("ERROR: target viewport file requires at least 3 boundary viewports")
    return parsed


def _anchor_for_node(node: dict, design_width: float, design_pixel_scale: float) -> dict:
    supplied = node.get("horizontalAnchor")
    if isinstance(supplied, dict) and supplied.get("mode") in {"left", "right", "center", "stretch"}:
        return supplied
    x, _, width, _ = [float(value) for value in node["bbox"]]
    right = design_width - x - width
    center_offset = x + width / 2.0 - design_width / 2.0
    if x >= 0 and right >= 0 and width >= design_width * 0.60:
        mode = "stretch"
    elif abs(center_offset) <= design_width * 0.03:
        mode = "center"
    elif right >= 0 and right <= design_width * 0.18 and x >= design_width * 0.45:
        mode = "right"
    else:
        mode = "left"
    return {
        "mode": mode,
        "left": x / design_pixel_scale,
        "right": right / design_pixel_scale,
        "centerOffset": center_offset / design_pixel_scale,
    }


def _responsive_rect(node: dict, viewport_width: float, design_width: float,
                     design_pixel_scale: float) -> list[float]:
    logical = node.get("logicalBbox")
    if not isinstance(logical, list) or len(logical) != 4:
        logical = [float(value) / design_pixel_scale for value in node["bbox"]]
    x, y, width, height = [float(value) for value in logical]
    anchor = _anchor_for_node(node, design_width, design_pixel_scale)
    if anchor["mode"] == "right":
        x = viewport_width - float(anchor["right"]) - width
    elif anchor["mode"] == "center":
        x = (viewport_width - width) / 2.0 + float(anchor["centerOffset"])
    elif anchor["mode"] == "stretch":
        x = float(anchor["left"])
        width = viewport_width - x - float(anchor["right"])
    return [round(value, 4) for value in (x, y, width, height)]


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument(
        "--expected", required=True,
        help="canonical merged_expected.json; when a canvas sidecar is supplied, an adjacent "
             "merged_expected.json beside --trace-out is adopted",
    )
    ap.add_argument("--page-import", required=True,
                    help="dart import line target, e.g. package:app/features/home/presentation/home_page.dart")
    ap.add_argument("--page-type", required=True, help="widget class under test, e.g. HomeArtboardCanvas")
    ap.add_argument("--page-expr", help="widget expr to pump as the REAL on-line page, injecting the "
                    "same-source design fixture, e.g. \"HomePage(repository: MockHomeRepository.design())\" "
                    "(default: '<PageType>()'). Trace the real page, not the canvas in isolation, so "
                    "page-level wrapping bugs (SafeArea offset, Stack collapse) are caught.")
    ap.add_argument("--extra-imports", default="",
                    help="comma-separated extra dart imports the page-expr needs (repository/fixture)")
    ap.add_argument("--trace-out", required=True, help="absolute path the test writes the trace JSON to")
    ap.add_argument("--responsive-out",
                    help="runtime responsive report (default: beside trace-out)")
    ap.add_argument("--responsive-contract-out",
                    help="generated responsive contract (default: beside trace-out)")
    ap.add_argument("--viewports", default="320x568,375x812,430x932",
                    help="comma-separated logical target viewports; minimum three")
    ap.add_argument("--viewports-file", type=Path,
                    help="project target viewport JSON; overrides --viewports")
    ap.add_argument("--safe-area-policy", choices=("edge_to_edge", "inset_content"),
                    default="edge_to_edge")
    ap.add_argument("--out", required=True, help="generated *_layout_trace_test.dart path")
    a = ap.parse_args()

    expected = _load_expected_contract(Path(a.expected), Path(a.trace_out))
    ids = list(expected.get("nodes", {}).keys())
    dw = expected.get("artboardWidth") or 750.0
    dh = expected.get("artboardHeight") or 5874.0
    page_expr = a.page_expr or f"{a.page_type}()"
    extra = "".join(f"import '{p.strip()}';\n" for p in a.extra_imports.split(",") if p.strip())

    ids_dart = ", ".join(f"'{i}'" for i in ids)
    viewports = _load_viewports(a.viewports, a.viewports_file)
    design_pixel_scale = float(expected.get("designPixelScale") or (float(dw) / 375.0))
    if design_pixel_scale <= 0:
        raise SystemExit("ERROR: expected designPixelScale must be > 0")
    logical_design_width = float(expected.get("logicalDesignWidth") or (float(dw) / design_pixel_scale))
    logical_design_height = float(dh) / design_pixel_scale
    responsive_nodes = {
        str(node_id): node for node_id, node in expected.get("nodes", {}).items()
        if isinstance(node, dict) and isinstance(node.get("bbox"), list) and len(node["bbox"]) == 4
    }
    responsive_rects_dart = ", ".join(
        f"{json.dumps(f'{float(width)}x{float(height)}')}: <String, List<double>>{{" +
        ", ".join(
            f"{json.dumps(node_id)}: <double>[{', '.join(repr(value) for value in _responsive_rect(node, width, dw, design_pixel_scale))}]"
            for node_id, node in responsive_nodes.items()
        ) + "}"
        for width, height in viewports
    )
    viewports_dart = ", ".join(
        f"<double>[{repr(width)}, {repr(height)}]" for width, height in viewports
    )
    responsive_out = Path(a.responsive_out) if a.responsive_out else (
        Path(a.trace_out).parent / "responsive_layout_report.json"
    )
    responsive_contract_out = Path(a.responsive_contract_out) if a.responsive_contract_out else (
        Path(a.trace_out).parent / "responsive_layout_contract.json"
    )
    responsive_contract_out.parent.mkdir(parents=True, exist_ok=True)
    responsive_contract_out.write_text(json.dumps({
        "schemaVersion": 2,
        "policy": "logical_375_constraints",
        "designWidth": float(dw),
        "designHeight": float(dh),
        "designPixelScale": design_pixel_scale,
        "logicalDesignWidth": logical_design_width,
        "runtimeScaleAllowed": False,
        "safeAreaPolicy": a.safe_area_policy,
        "verticalBehavior": "scroll",
        "viewportSource": str(a.viewports_file) if a.viewports_file else "default_phone_boundaries",
        "viewports": [
            {"width": width, "height": height} for width, height in viewports
        ],
        "nodeConstraints": {
            node_id: {
                "logicalBbox": _responsive_rect(node, logical_design_width, dw, design_pixel_scale),
                "horizontalAnchor": _anchor_for_node(node, dw, design_pixel_scale),
            }
            for node_id, node in responsive_nodes.items()
        },
    }, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    dart = (TEMPLATE
            .replace("__PAGE_IMPORT__", f"import '{a.page_import}';")
            .replace("__EXTRA_IMPORTS__", extra)
            .replace("__DW__", repr(logical_design_width))
            .replace("__DH__", repr(logical_design_height))
            .replace("__PAGE_EXPR__", page_expr)
            .replace("__PAGE_TYPE_STR__", a.page_type)
            .replace("__PAGE_TYPE__", a.page_type)
            .replace("__IDS__", ids_dart)
            .replace("__RESPONSIVE_RECTS__", responsive_rects_dart)
            .replace("__VIEWPORTS__", viewports_dart)
            .replace("__TRACE_OUT__", a.trace_out)
            .replace("__RESPONSIVE_OUT__", str(responsive_out)))

    out = Path(a.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(dart, encoding="utf-8")
    print(json.dumps({"out": str(out), "ids": len(ids), "designWidth": dw, "designHeight": dh,
                      "traceOut": a.trace_out, "responsiveOut": str(responsive_out),
                      "responsiveContractOut": str(responsive_contract_out),
                      "viewports": viewports}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
